{
  "apiVersion": 1,
  "type": "component.detail",
  "package": "@astryxdesign/core",
  "data": {
    "name": "DropdownMenuCheckboxItem",
    "subComponentOf": "DropdownMenu",
    "displayName": "Dropdown Menu Checkbox Item",
    "isHiddenFromOverview": true,
    "description": "A checkable menu item (role=\"menuitemcheckbox\") that toggles an independent boolean. Use for on/off options inside a DropdownMenu; for a one-of-N choice use DropdownMenuRadioGroup.",
    "usage": {
      "anatomy": [
        {
          "name": "Checkable row",
          "required": true,
          "description": "The menuitemcheckbox root that owns the accessible name, checked state, focus, and activation."
        },
        {
          "name": "Label/content",
          "required": true,
          "description": "Caller content laid out by Item: the required label plus optional description, icon, and end content."
        },
        {
          "name": "Checkbox marker",
          "required": true,
          "description": "Decorative shared Indicator chrome that visualizes checked and disabled state without adding a second control."
        }
      ],
      "description": "An independently checkable option inside DropdownMenu. The row owns menuitemcheckbox semantics while the shared Indicator supplies decorative checkbox paint."
    },
    "props": [
      {
        "name": "label",
        "type": "ReactNode",
        "description": "Primary label text identifying the item."
      },
      {
        "name": "description",
        "type": "ReactNode",
        "description": "Secondary description text displayed below the label."
      },
      {
        "name": "icon",
        "type": "IconType",
        "description": "Icon to display before the label. See `astryx docs icons` for valid semantic names."
      },
      {
        "name": "value",
        "type": "boolean",
        "description": "Whether the item is checked. Controlled; pair with onChange."
      },
      {
        "name": "onChange",
        "type": "(checked: boolean) => void",
        "description": "Callback fired with the next checked state when the item is toggled."
      },
      {
        "name": "isDisabled",
        "type": "boolean",
        "default": "false",
        "description": "Whether the item is disabled. A disabled item stays in the accessibility tree as disabled (aria-disabled), and the arrow keys and typeahead reach it so keyboard users find it. The pointer highlight skips it, and activation is blocked."
      },
      {
        "name": "hasCloseOnSelect",
        "type": "boolean",
        "default": "false",
        "description": "Whether toggling the item closes the menu. Checkbox items default to staying open so several can be toggled in a single session."
      },
      {
        "name": "ref",
        "type": "React.Ref<HTMLElement>",
        "description": "Ref forwarded to the row root, the element carrying role=\"menuitemcheckbox\". Register the row with an element-keyed observer or overlay."
      },
      {
        "name": "endContent",
        "type": "ReactNode",
        "description": "Content to render after the label and description, such as a keyboard shortcut hint or badge."
      }
    ],
    "theming": {
      "targets": [
        {
          "className": "astryx-dropdown-menu-item",
          "visualProps": [
            "size"
          ]
        }
      ]
    },
    "package": "@astryxdesign/core",
    "import": "@astryxdesign/core/DropdownMenu",
    "sourceAvailable": true
  },
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
